  final _Harness _harness;

  @override
  Future<Object?> send(String method, String path, {Map<String, Object?> query = const {}, Object? jsonBody, bool hasBody = false, bool bytesAnswer = false, required String accept}) {
    return _harness.dispatch(_harness.call(method, path, query, hasBody ? jsonBody : null));
  }

  @override
  Future<Object?> sendMultipart(String method, String path, {Map<String, Object?> query = const {}, required Map<String, String?> fields, required Map<String, UploadFile?> files, bool bytesAnswer = false, required String accept}) {
    final parts = <String, Object?>{
      ...fields,
      for (final entry in files.entries)
        if (entry.value != null) entry.key: entry.value!.filename,
    };
    return _harness.dispatch(_harness.call(method, path, query, parts));
  }
}

String _canonical(Object? value) {
  if (value is Map) {
    final keys = value.keys.map((key) => '$key').toList()..sort();
    return '{${keys.map((key) => '${jsonEncode(key)}:${_canonical(value[key])}').join(',')}}';
  }
  if (value is List) {
    return '[${value.map(_canonical).join(',')}]';
  }
  return jsonEncode(value);
}

