/// Starts one test of [app]: a fresh role-only session, persisted state over
/// an in-memory store, and a runtime whose every call the test answers.
Future<void> dtxStartUiTest(WidgetTester tester, DtxTestApp app) async {
  SharedPreferencesAsyncPlatform.instance = InMemorySharedPreferencesAsync.empty();
  final harness = _Harness(tester, app);
  final strings = await tester.runAsync(() => AppStrings.load(app.stringsAsset));
  if (strings == null) {
    throw StateError('The strings catalog ${app.stringsAsset} did not load.');
  }
  await tester.runAsync(loadFormatData);
  final session = _TestSession(strings);
  final persisted = await tester.runAsync(() => PersistedState.load(strings.appKey, session));
  if (persisted == null) {
    throw StateError('The persisted state of ${strings.appKey} did not load.');
  }
  final navigatorKey = GlobalKey<NavigatorState>();
  harness.session = session;
  harness.runtime = DatrixRuntime(config: _testConfig, session: session, strings: strings, router: app.buildRouter(navigatorKey, session), navigatorKey: navigatorKey, persisted: persisted, link: const UnlinkedDevice(), transport: _TestTransport(harness));
  installDatrixRuntime(harness.runtime);
  _current = harness;
  addTearDown(() {
    _current = null;
    harness.finish();
  });
}

/// The mounted app, as a test drives it.
class DtxScreen {
  const DtxScreen._(this._h);

  final _Harness _h;

  Future<void> tap(String kind, Object? name) async {
    await _h.tester.tap(_one(kind, name));
    await _h.settle();
  }

  Future<void> enter(String kind, Object? name, Object? value) async {
    final field = find.descendant(of: _one(kind, name), matching: find.byType(EditableText));
    await _h.tester.enterText(field, textOf(value));
    await _h.settle();
  }

  Future<void> select(String kind, Object? name, List<Object?> values) async {
    final element = _one(kind, name);
    if (kind == 'select') {
      await _h.tester.tap(element);
      await _h.settle();
      for (final value in values) {
        await _h.tester.tap(find.text(textOf(value)).last);
        await _h.settle();
      }
      return;
    }
    if (kind != 'multiSelect' && kind != 'radio') {
      throw ArgumentError.value(kind, 'kind', 'screen.select chooses in a select, a multiSelect or a radio group');
    }
    for (final value in values) {
      await _h.tester.tap(find.descendant(of: element, matching: find.text(textOf(value))));
      await _h.settle();
    }
  }

  bool shows(Object? text) => find.text(textOf(text), findRichText: true).evaluate().isNotEmpty;

  Finder _one(String kind, Object? name) {
    final matches = _kinds[kind];
    if (matches == null) {
      throw ArgumentError.value(kind, 'kind', 'Not an element a test can find by its label');
    }
    final label = textOf(name);
    final finder = find.byWidgetPredicate((widget) => matches(widget, label), description: '$kind "$label"');
    final count = finder.evaluate().length;
    if (count != 1) {
      throw TestFailure('screen: expected exactly one $kind labelled "$label", found $count.');
    }
    return finder;
  }
}

bool _menuItem(Widget widget, String label) {
  if (widget is! PopupMenuItem) {
    return false;
  }
  final child = widget.child;
  final text = child is DtxStack && child.children.isNotEmpty ? child.children.first : child;
  return text is Text && text.data == label;
}

/// Each findable element kind, and how a widget is that kind with that label.
final Map<String, bool Function(Widget widget, String label)> _kinds = {
  'button': (widget, label) => widget is DtxButton && widget.label == label,
  'iconButton': (widget, label) => widget is DtxIconButton && widget.label == label,
  'link': (widget, label) => widget is DtxLink && widget.label == label,
  'menuItem': _menuItem,
  'tab': (widget, label) => widget is Tab && widget.text == label,
  'input': (widget, label) => widget is DtxTextInput && widget.kind == DtxTextKind.text && widget.label == label,
  'textArea': (widget, label) => widget is DtxTextInput && widget.kind == DtxTextKind.multiline && widget.label == label,
  'search': (widget, label) => widget is DtxTextInput && widget.kind == DtxTextKind.search && widget.label == label,
  'number': (widget, label) => widget is DtxNumberInput && widget.label == label,
  'select': (widget, label) => widget is DtxSelect && widget.label == label,
  'multiSelect': (widget, label) => widget is DtxMultiSelect && widget.label == label,
  'checkbox': (widget, label) => widget is DtxCheck && !widget.toggle && widget.label == label,
  'toggle': (widget, label) => widget is DtxCheck && widget.toggle && widget.label == label,
  'radio': (widget, label) => widget is DtxRadioGroup && widget.label == label,
  'slider': (widget, label) => widget is DtxSlider && widget.label == label,
};

/// `render(Page, args...)` / `render(Component, ...)`.
Future<DtxScreen> dtxRenderScreen(DtxMount target, [Map<String, Object?> args = const {}]) async {
  final harness = _harness;
  await harness.mount(target, args);
  return DtxScreen._(harness);
}

/// `navigated(Page, args...)`: whether the app shows that page's route.
bool dtxUiTestNavigated(String pathTemplate, [Map<String, Object?> args = const {}]) {
  final runtime = _harness.runtime;
  return runtime.router.routerDelegate.currentConfiguration.uri.path == runtime.nav.url(pathTemplate, args);
}

/// `respond(call, value)`: [call] is answered with [value], as the backend
/// would send it.
void dtxUiTestRespond(Future<Object?> Function() call, Object? value) {
  final harness = _harness;
  harness.answer(harness.capture(call), _Answer.value(jsonDecode(jsonEncode(value))));
}

/// `respondError(call, exception)`: [call] fails with [error].
void dtxUiTestRespondError(Future<Object?> Function() call, Object error) {
  final harness = _harness;
  harness.answer(harness.capture(call), _Answer.error(error));
}

/// `called(call)`: whether the app made [call] with those arguments.
bool dtxUiTestCalled(Future<Object?> Function() call) {
  final harness = _harness;
  return harness.made(harness.capture(call));
}

/// `sample(Type, member: value)`: the generator already built the value.
T dtxUiTestSample<T>(T value) => value;

/// `signIn(roles)`: a session holding exactly [roles].
Future<void> dtxUiTestSignIn(List<String> roles) async {
  final harness = _harness;
  harness.session.signIn(roles);
  await harness.settle();
}

/// `signOut()`: the session ends, running every logout and session-end hook.
Future<void> dtxUiTestSignOut() async {
  final harness = _harness;
  await harness.session.logout();
  await harness.settle();
}

/// `answerConfirm(answer)`: what the next `Ui.confirm` receives.
void dtxUiTestAnswerConfirm(bool answer) {
  _harness.queueConfirm(answer);
}
